<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['acao']??'';$id=(int)($_POST['id']??0);if($action==='excluir'){$s=db()->prepare("UPDATE produtos SET ativo=0 WHERE id=?");$s->execute([$id]);}header('Location: produtos.php');exit;}
$products=db()->query("SELECT p.*,c.nome categoria FROM produtos p JOIN categorias c ON c.id=p.categoria_id ORDER BY p.id DESC")->fetchAll();$pageTitle='Produtos';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h2">Produtos</h1><a class="btn btn-dark" href="produto-form.php">Novo produto</a></div><div class="table-responsive card"><table class="table table-hover mb-0"><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= e($p['nome']) ?></td><td><?= e($p['categoria']) ?></td><td><?= money($p['preco']) ?></td><td><?= (int)$p['estoque'] ?></td><td><?= $p['ativo']?'Ativo':'Inativo' ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="produto-form.php?id=<?= (int)$p['id'] ?>">Editar</a><?php if($p['ativo']): ?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Desativar este produto?">Desativar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
